	public static void Main(Args _args)
    {
        MultiSelectionHelper	mh = MultiSelectionHelper::construct();
        MobToteTable			mt;
        FormDataSource			ds = _args.record().dataSource();
        ttsbegin;
        mh.parmDatasource(ds);
        for ( mt = mh.getFirst(); mt != null; mt = mh.getNext())
        {
            mt.selectForUpdate(true);
            mt.Shipped = true;
            mt.update();
        }
        ttscommit;
        ds.executeQuery();
    }
